#include <gtk/gtk.h>
#include <vte/vte.h>
#include <stdio.h>
static const char *phase = "initial";
static void commit_cb(VteTerminal *term, const char *text, guint size, gpointer data) {
    printf("commit phase=%s hex=", phase);
    for (guint i=0;i<size;i++) printf("%02x", (unsigned char)text[i]);
    printf("\n");
}
static void drain(void) {
    gint64 end = g_get_monotonic_time() + 200000;
    while (g_get_monotonic_time() < end) {
        while (g_main_context_iteration(NULL, FALSE)) {}
        g_usleep(1000);
    }
}
int main(void) {
    gtk_init();
    printf("VTE=%u.%u.%u\n", vte_get_major_version(), vte_get_minor_version(), vte_get_micro_version());
    GtkWidget *window = gtk_window_new();
    GtkWidget *term = vte_terminal_new();
    gtk_window_set_child(GTK_WINDOW(window), term);
    gtk_window_present(GTK_WINDOW(window));
    gtk_widget_grab_focus(term);
    drain();
    g_signal_connect(term, "commit", G_CALLBACK(commit_cb), NULL);
    GListModel *controllers = gtk_widget_observe_controllers(term);
    for (guint i=0;i<g_list_model_get_n_items(controllers);i++) {
        GObject *controller = g_list_model_get_item(controllers, i);
        if (GTK_IS_EVENT_CONTROLLER_KEY(controller)) {
            printf("key_controller=%s im_context=%s\n",
              gtk_event_controller_get_name(GTK_EVENT_CONTROLLER(controller)),
              gtk_event_controller_key_get_im_context(GTK_EVENT_CONTROLLER_KEY(controller)) ? "available" : "NULL");
        }
        g_object_unref(controller);
    }
    g_object_unref(controllers);
    phase = "feed_child_ASCII";
    vte_terminal_feed_child(VTE_TERMINAL(term), "x", 1);
    phase = "feed_child_arrow";
    vte_terminal_feed_child(VTE_TERMINAL(term), "\x1b[D", 3);
    phase = "enable_focus_reporting";
    vte_terminal_feed(VTE_TERMINAL(term), "\x1b[?1004h", -1);
    drain();
    phase = "focus_cycle";
    gtk_window_set_focus(GTK_WINDOW(window), NULL);
    gtk_widget_grab_focus(term);
    drain();
    gtk_window_destroy(GTK_WINDOW(window));
    return 0;
}
